namespace Ck3MapGen.MapGen;

/// <summary>
/// Vanilla CK3 1.21.0's trade-good placement, measured from its
/// <c>county_potential_trade_goods.txt</c> over its 3,549 counties by
/// <c>ck3devtools\calibration\trade_goods_mine.py</c> (re-run after a patch moves the file and
/// paste its <c>tg_table.cs.txt</c> over the rows below).
///
/// Per good: its share of vanilla counties; its clumping (how much likelier a county's neighbour
/// has it than chance); and lifts, each = the good's rate in that condition over the overall rate,
/// smoothed with 3 pseudo-counts. Terrain lifts are over baronies, in <see cref="Terrains"/>
/// order. Coast is {touches sea or lake, not}; river {touches a major river, not}; winter is
/// {bias 0, under 0.42, under 0.70, 0.70 and above}, the median and upper quartile of vanilla's
/// counties above zero.
///
/// Goods vanilla never places on a county (cheese, meat, leather, beer, textiles, glass, jewelry,
/// lacquerware, books) come from buildings, not land, and are not here. Vanilla's 1.21 terraced
/// terrain has no generated counterpart, so its counties count toward every share but no lift.
/// </summary>
public static class TradeGoodTable
{
    public sealed record Good(string Key, double Share, double Clumping,
        double[] Terrain, double[] Coast, double[] River, double[] Winter);

    public static readonly string[] Terrains =
        ["plains", "farmlands", "steppe", "drylands", "desert", "jungle", "forest", "taiga", "wetlands",
         "floodplains", "hills", "mountains", "desert_mountains", "oasis"];

    public static int TerrainIndex(TerrainClass t)
    {
        int i = Array.IndexOf(Terrains, TerrainClassifier.Name(t));
        return i < 0 ? 0 : i;
    }

    public static int WinterBucket(double bias) => bias < 1e-6 ? 0 : bias < 0.4167 ? 1 : bias < 0.70 ? 2 : 3;

